css:
.agua-sim-container { padding: 28px; background: linear-gradient(180deg, #e8f5e9 0%, #c8e6c9 100%); min-height: 100vh; font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif; color: #1b4332; }
.agua-sim-header { display: flex; justify-content: space-between; align-items: center; background: linear-gradient(135deg, #1b4332, #2d6a4f 55%, #40916c); color: #d8f3dc; border-radius: 24px; padding: 32px 36px; margin-bottom: 28px; box-shadow: 0 14px 36px rgba(27,67,50,0.28); }
.agua-sim-title-block h1 { margin: 0; font-size: 1.75rem; font-weight: 700; letter-spacing: -0.01em; }
.agua-sim-subtitle { margin: 6px 0 0 0; font-size: 0.95rem; color: #b7e4c7; }
.agua-sim-period-badge { background: rgba(255,255,255,0.15); border: 1px solid rgba(255,255,255,0.25); border-radius: 999px; padding: 10px 18px; font-size: 0.95rem; font-weight: 600; letter-spacing: 0.03em; }
.agua-sim-period-badge span { margin: 0 3px; }
.agua-sim-briefing { background: white; border-left: 6px solid #2d6a4f; border-radius: 16px; padding: 24px 28px; margin-bottom: 28px; box-shadow: 0 6px 20px rgba(0,0,0,0.06); }
.agua-sim-briefing-header { display: flex; justify-content: space-between; align-items: center; margin-bottom: 8px; }
.agua-sim-briefing-tag { background: #d8f3dc; color: #1b4332; border-radius: 999px; padding: 4px 14px; font-size: 0.75rem; font-weight: 700; text-transform: uppercase; letter-spacing: 0.08em; }
.agua-sim-briefing-duration { color: #52796f; font-size: 0.85rem; font-weight: 600; }
.agua-sim-briefing h2 { margin: 10px 0 8px; font-size: 1.25rem; color: #1b4332; }
.agua-sim-briefing p { margin: 0; color: #2d3a36; line-height: 1.55; }
.agua-sim-kpi-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(200px, 1fr)); gap: 18px; margin-bottom: 28px; }
.agua-sim-kpi-card { background: white; border-radius: 18px; padding: 22px 20px; border-top: 5px solid #52b788; box-shadow: 0 6px 18px rgba(27,67,50,0.10); transition: transform 0.2s ease; }
.agua-sim-kpi-card:hover { transform: translateY(-3px); }
.agua-sim-kpi-cash { border-top-color: #2d6a4f; }
.agua-sim-kpi-production { border-top-color: #95d5b2; }
.agua-sim-kpi-water { border-top-color: #48cae4; }
.agua-sim-kpi-profit { border-top-color: #d4a373; }
.agua-sim-kpi-label { font-size: 0.75rem; text-transform: uppercase; letter-spacing: 0.1em; color: #52796f; margin-bottom: 8px; font-weight: 600; }
.agua-sim-kpi-value { font-size: 1.8rem; font-weight: 700; color: #1b4332; }
.agua-sim-controls { background: white; border-radius: 20px; padding: 28px; margin-bottom: 28px; box-shadow: 0 6px 20px rgba(0,0,0,0.06); }
.agua-sim-controls h3 { margin-top: 0; margin-bottom: 20px; color: #1b4332; font-size: 1.15rem; }
.agua-sim-decision-row { margin-bottom: 16px; }
.agua-sim-decision-row label { display: block; font-size: 0.9rem; font-weight: 600; color: #2d6a4f; margin-bottom: 6px; }
.agua-sim-controls input, .agua-sim-controls select { width: 100%; background: #ffffff; border: 1px solid #52b788; color: #1b4332; border-radius: 10px; padding: 10px 14px; font-size: 0.95rem; }
.agua-sim-controls select option { background: #ffffff; color: #1b4332; }
.agua-sim-controls input:focus, .agua-sim-controls select:focus { outline: none; border-color: #2d6a4f; box-shadow: 0 0 0 3px rgba(45,106,79,0.18); }
.agua-sim-buttons { display: flex; gap: 12px; align-items: center; margin-top: 20px; }
.agua-sim-buttons .btn-primary { background: #2d6a4f; border-color: #2d6a4f; color: #fff; padding: 10px 22px; border-radius: 10px; font-weight: 600; }
.agua-sim-buttons .btn-primary:hover { background: #1b4332; border-color: #1b4332; }
.agua-sim-buttons .btn-outline-secondary { border-radius: 10px; }
.agua-sim-results-panel { background: #f1faee; border-radius: 16px; padding: 22px 26px; margin-bottom: 28px; border: 1px dashed #95d5b2; }
.agua-sim-results-panel h3 { margin-top: 0; color: #1b4332; font-size: 1.05rem; }
.agua-sim-results-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(180px, 1fr)); gap: 14px; color: #2d3a36; font-size: 0.95rem; }
.agua-sim-results-grid strong { color: #1b4332; }
.agua-sim-history { background: white; border-radius: 18px; padding: 22px; margin-bottom: 28px; box-shadow: 0 6px 18px rgba(0,0,0,0.06); }
.agua-sim-history h3 { margin-top: 0; color: #1b4332; font-size: 1.05rem; }
.agua-sim-history table { width: 100%; color: #1b4332; }
.agua-sim-history th { background: #d8f3dc; color: #1b4332; }
.agua-sim-chart-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(340px, 1fr)); gap: 22px; margin-bottom: 28px; }
.agua-sim-chart-card { background: white; border-radius: 18px; padding: 20px; box-shadow: 0 6px 18px rgba(0,0,0,0.06); height: 320px; }
@media (max-width: 768px) { .agua-sim-header { flex-direction: column; align-items: flex-start; gap: 14px; } .agua-sim-kpi-value { font-size: 1.4rem; } .agua-sim-buttons { flex-direction: column; align-items: stretch; } }
/* --- v1.1.0: nota acumulada, cosecha no vendida y panel de cierre --- */
.agua-sim-kpi-score { border-left: 4px solid #40916c; }
.agua-sim-help { display: block; margin-top: .25rem; font-size: .8125rem; color: #52796f; line-height: 1.35; }
.agua-sim-debrief { margin: 1.5rem 0; padding: 1.25rem 1.5rem; border: 1px solid #b7e4c7;
  border-radius: 10px; background: #f1faf4; }
.agua-sim-debrief h3 { margin: 0 0 1rem; color: #1b4332; }
.agua-sim-debrief h4 { margin: 1.1rem 0 .5rem; font-size: .95rem; color: #2d6a4f; text-transform: uppercase;
  letter-spacing: .04em; }
.agua-sim-debrief-grade { display: flex; align-items: baseline; gap: 1rem; flex-wrap: wrap; }
.agua-sim-debrief-score { font-size: 2.5rem; font-weight: 700; color: #1b4332; line-height: 1; }
.agua-sim-debrief-score small { font-size: 1rem; font-weight: 400; color: #52796f; }
.agua-sim-debrief-tier { padding: .3rem .85rem; border-radius: 999px; background: #2d6a4f; color: #fff;
  font-weight: 600; font-size: .95rem; }
.agua-sim-debrief-kpis { display: grid; grid-template-columns: repeat(auto-fit, minmax(160px, 1fr));
  gap: .75rem; margin-top: 1rem; }
.agua-sim-debrief-kpis > div { display: flex; flex-direction: column; padding: .6rem .75rem;
  background: #fff; border: 1px solid #d8f3dc; border-radius: 8px; }
.agua-sim-debrief-kpis span { font-size: .78rem; color: #52796f; text-transform: uppercase; letter-spacing: .03em; }
.agua-sim-debrief-kpis strong { font-size: 1.05rem; color: #1b4332; margin-top: .15rem; }
.agua-sim-debrief-components { list-style: none; margin: 0; padding: 0; }
.agua-sim-debrief-components li { display: flex; justify-content: space-between; gap: 1rem;
  padding: .4rem 0; border-bottom: 1px dashed #d8f3dc; }
.agua-sim-debrief-components li:last-child { border-bottom: 0; }
.agua-sim-debrief-insights { margin: 0; padding-left: 1.2rem; }
.agua-sim-debrief-insights li { margin-bottom: .4rem; line-height: 1.45; }
@media (max-width: 640px) {
  .agua-sim-debrief { padding: 1rem; }
  .agua-sim-debrief-score { font-size: 2rem; }
}

