            ds.capexStock = newStock;
            ds.waterEfficiency = Math.min(0.98,
                this.EFF_BASE + Math.min(this.EFF_MAX_GAIN, ds.capexStock / this.CAPEX_MAX * this.EFF_MAX_GAIN));

            const sugarShare = d.cropMix / 100;
            const riceShare = 1 - sugarShare;
            const cropWaterIntensity = sugarShare * 1.40 + riceShare * 1.00;
            const waterStress = Math.max(0, (1 - round.rainfallIndex) * cropWaterIntensity * (1 - ds.waterEfficiency));
            const yieldFactor = Math.max(0.35, 1 - waterStress);

            const potentialProduction = round.demandBase;
            const production = Math.round(potentialProduction * yieldFactor);

            const strat = this.STRATEGIES[d.strategy] || this.STRATEGIES.balanced;
            const strategyMultiplier = strat.multiplier;
            const strategyCost = strat.cost;

            const priceRatio = d.price / round.priceIndex;
            const priceElasticity = Math.max(0.25, Math.min(1.50, 2 - priceRatio));
            const demand = Math.round(production * priceElasticity * strategyMultiplier);
            const realizedSales = Math.min(demand, production);
            const unsold = production - realizedSales;

            // Correccion de unidades: el indice de precio se traduce a COP/kg reales.
            // La formula anterior dividia por 1000 el ingreso, dejando COP ~100.000 por
            // tonelada frente a un coste variable de COP 1,4-1,8 M/t: perdida garantizada
            // en todas las rondas y con cualquier decision.
            const priceCOPPerKg = d.price / 100 * this.PRICE_AT_INDEX_100;
            const revenue = realizedSales * 1000 * priceCOPPerKg;

            const variableCostPerTon = sugarShare * 1800000 + riceShare * 1400000;
            // El coste variable se causa sobre lo PRODUCIDO, no sobre lo vendido: sembrar
            // y no vender ya no es gratis, lo que elimina la estrategia dominante de
            // fijar el precio al maximo para recortar coste sin perder ingreso.
            const variableCosts = production * variableCostPerTon;
            const salvage = unsold * variableCostPerTon * this.SALVAGE_RATE;
            const fixedCosts = this.FIXED_COSTS;
            const investmentCOP = capexSpend * 1000000;
            const strategyCostCOP = strategyCost * 1000000;
            const totalCosts = variableCosts + fixedCosts + investmentCOP + strategyCostCOP - salvage;

            const profit = revenue - totalCosts;

            ds.production = production;
            ds.unsold = unsold;
            ds.cash += profit;
            ds.totalProfit += profit;
            ds.producedTotal = (ds.producedTotal || 0) + production;
            ds.unsoldTotal = (ds.unsoldTotal || 0) + unsold;
            ds.minCash = Math.min(ds.minCash === undefined ? this.START_CASH : ds.minCash, ds.cash);
            ds.profitHistory.push(profit);
            ds.waterHistory.push(Math.round(ds.waterEfficiency * 100));
            ds.productionHistory.push(production);

            // Contrato de calificacion: express_resolveDomainScore() lee
            // domainState.performance.overallScore -> .score -> .netWorth. Nada de eso
            // existia, por lo que ninguna sesion devolvia nota.
            const perf = this._score(ds);
            ds.performance = perf;
            ds.score = perf.overallScore;
            ds.scoreHistory.push(perf.overallScore);

            const isFinal = (state.currentPeriod || 1) >= (state.maxPeriods || this.ROUNDS.length);
            var self = this;
            // El repintado leia state.currentPeriod + 1 con 500 ms de retraso, pero el
            // motor ya habia incrementado el periodo: el briefing saltaba dos rondas.
            setTimeout(function() {
                try {
                    const live = (window.mySimulation && window.mySimulation.state) || state;
                    if (isFinal) { self._renderDebrief(live); return; }
                    self._updateBriefing(live);
                } catch (e) { /* no romper el ciclo de la ronda */ }
            }, 0);

            return {
                period: state.currentPeriod,
                production: production,
                demand: demand,
                sales: realizedSales,
                unsold: unsold,
                revenue: revenue,
                costs: totalCosts,
                profit: profit,
                pricePerKg: Math.round(priceCOPPerKg),
                capexSpend: capexSpend,
                capexStock: ds.capexStock,
                waterEfficiency: Math.round(ds.waterEfficiency * 100),
                overallScore: perf.overallScore,
                cash: ds.cash
            };
        }

        _clamp(v, a, b) { return Math.max(a, Math.min(b, v)); }

        // Nota 0-100 publicada cada ronda. Pesos: rentabilidad 45, eficiencia hidrica 25,
        // solvencia 15, aprovechamiento de la cosecha 15.
        _score(ds) {
            const profitability = this._clamp(50 + 50 * (ds.totalProfit / 6000000000), 0, 100);
            const water = this._clamp((ds.waterEfficiency - this.EFF_BASE) / 0.38 * 100, 0, 100);
            const solvency = this._clamp((ds.minCash === undefined ? this.START_CASH : ds.minCash) / this.START_CASH * 100, 0, 100);
            const wasteRate = ds.producedTotal > 0 ? ds.unsoldTotal / ds.producedTotal : 0;
            const harvestUse = this._clamp(100 - wasteRate * 250, 0, 100);
            const overall = Math.round((profitability * 0.45 + water * 0.25 + solvency * 0.15 + harvestUse * 0.15) * 10) / 10;
            const tier = this.TIERS.find((t) => overall >= t.min) || this.TIERS[this.TIERS.length - 1];
            return {
                overallScore: overall,
                score: overall,
                tierKey: tier.key,
                tier: this._t(tier.key),
                components: {
                    profitability: Math.round(profitability * 10) / 10,
                    waterEfficiency: Math.round(water * 10) / 10,
                    solvency: Math.round(solvency * 10) / 10,
                    harvestUse: Math.round(harvestUse * 10) / 10
                }
            };
        }

        _updateBriefing(state) {
            const idx = Math.min((state.currentPeriod || 1) - 1, this.ROUNDS.length - 1);
            const round = this.ROUNDS[idx];
            const t = (k) => this._t(k);

            const tagEl = document.getElementById('roundTag');
            if (tagEl) tagEl.textContent = t(round.tagKey);
            const titleEl = document.getElementById('roundTitle');
            if (titleEl) titleEl.textContent = t(round.titleKey);
            const briefEl = document.getElementById('briefingText');
            if (briefEl) briefEl.textContent = t(round.briefKey);
            const durEl = document.getElementById('roundDuration');
            if (durEl) durEl.textContent = round.duration;
        }

        _hideDebrief() {
            const panel = document.getElementById('debriefPanel');
            if (panel) panel.style.display = 'none';
        }

        _debriefHTML(ds) {
            const perf = ds.performance || this._score(ds);
            const c = perf.components || {};
            const rows = [
                ['debrief_profitability', c.profitability],
                ['debrief_water', c.waterEfficiency],
                ['debrief_solvency', c.solvency],
                ['debrief_harvest', c.harvestUse]
            ].map((r) => '<li><span>' + this._t(r[0]) + '</span><strong>' + (r[1] === undefined ? '—' : r[1]) + ' / 100</strong></li>').join('');
            const insights = this._insights(ds).map((s) => '<li>' + s + '</li>').join('');
            return '<div class="agua-sim-debrief-grade">' +
                '<span class="agua-sim-debrief-score">' + perf.overallScore + '<small> / 100</small></span>' +
                '<span class="agua-sim-debrief-tier">' + this._t(perf.tierKey || 'tier_beginner') + '</span>' +
                '</div>' +
                '<div class="agua-sim-debrief-kpis">' +
                '<div><span>' + this._t('profit_label') + '</span><strong>' + this._fmtCOP(ds.totalProfit) + '</strong></div>' +
                '<div><span>' + this._t('cash_label') + '</span><strong>' + this._fmtCOP(ds.cash) + '</strong></div>' +
                '<div><span>' + this._t('water_label') + '</span><strong>' + Math.round(ds.waterEfficiency * 100) + '%</strong></div>' +
                '<div><span>' + this._t('debrief_capex') + '</span><strong>' + this._fmtCOP((ds.capexStock || 0) * 1000000) + '</strong></div>' +
                '</div>' +
                '<h4>' + this._t('debrief_components') + '</h4><ul class="agua-sim-debrief-components">' + rows + '</ul>' +
                '<h4>' + this._t('debrief_insights') + '</h4><ul class="agua-sim-debrief-insights">' + insights + '</ul>';
        }

        _renderDebrief(state) {
            const ds = (state && state.domainState) || {};
            const panel = document.getElementById('debriefPanel');
            const body = document.getElementById('debriefContent');
            if (!panel || !body) return;
            const head = document.getElementById('debriefHeading');
            if (head) head.textContent = this._t('debrief_heading');
            body.innerHTML = this._debriefHTML(ds);
            panel.style.display = 'block';
        }

        _insights(ds) {
            const out = [];
            const perf = ds.performance || {};
            const c = perf.components || {};
            const wasteRate = ds.producedTotal > 0 ? ds.unsoldTotal / ds.producedTotal : 0;
            if (ds.totalProfit > 0) out.push(this._t('insight_profit_ok'));
            else out.push(this._t('insight_profit_bad'));
            if ((ds.capexStock || 0) >= this.CAPEX_MAX * 0.75) out.push(this._t('insight_capex_high'));
            else if ((ds.capexStock || 0) <= this.CAPEX_MAX * 0.25) out.push(this._t('insight_capex_low'));
            if (wasteRate > 0.12) out.push(this._t('insight_waste'));
            if (c.solvency !== undefined && c.solvency < 60) out.push(this._t('insight_solvency'));
            return out;
        }

        formatCompletionMessage(summary) {
            const ds = (summary && summary.domainState) ||
                (window.mySimulation && window.mySimulation.state && window.mySimulation.state.domainState) || {};
            this._renderDebrief({ domainState: ds });
            return this._debriefHTML(ds);
        }

