            const self = this;
            uiManager.bind('currentDay', 'currentPeriod');
            uiManager.bind('maxPeriods', 'maxPeriods');
            uiManager.bind('cashDisplay', 'domainState.cash', (v) => self._fmtCOP(v));
            uiManager.bind('productionDisplay', 'domainState.production', (v) => self._fmtTon(v));
            uiManager.bind('waterDisplay', 'domainState.waterEfficiency', (v) => Math.round(v * 100) + '%');
            uiManager.bind('totalProfitDisplay', 'domainState.totalProfit', (v) => self._fmtCOP(v));
            uiManager.bind('scoreDisplay', 'domainState.performance.overallScore', (v) => v + ' / 100');
            uiManager.bind('demandDisplay', 'results.demand', (v) => self._fmtTon(v));
            uiManager.bind('revenueDisplay', 'results.revenue', (v) => self._fmtCOP(v));
            uiManager.bind('costsDisplay', 'results.costs', (v) => self._fmtCOP(v));
            uiManager.bind('profitDisplay', 'results.profit', (v) => self._fmtCOP(v));
            uiManager.bind('unsoldDisplay', 'results.unsold', (v) => self._fmtTon(v));
