        getChartData(state) {
            const ds = state.domainState || {};
            const profits = ds.profitHistory || [];
            const labels = profits.map((_, i) => this._t('round_short') + (i + 1));
            return {
                profitChart: { labels: labels, datasets: [{ data: profits.map((v) => Math.round(v / 1000000)) }] },
                waterChart: { labels: labels, datasets: [{ data: ds.waterHistory || [] }] }
            };
        }

        getHint(state, results) {
            if (results && results.profit < 0) return this._t('hint_loss');
            if (results && results.unsold > results.production * 0.12) return this._t('hint_waste');
            if (state.domainState.waterEfficiency < 0.7) return this._t('hint_water');
            if (results && results.demand > results.production) return this._t('hint_shortage');
            return null;
        }

