            const self = this;
            return [
                { key: 'decisions.cropMix', label: 'Caña %', i18nKey: 'col_crop', formatter: (v) => v + '%' },
                { key: 'decisions.waterInvestment', label: 'Inv. riego', i18nKey: 'col_water_inv', formatter: (v) => v + ' M' },
                { key: 'decisions.price', label: 'Precio idx', i18nKey: 'col_price' },
                { key: 'decisions.strategy', label: 'Estrategia', i18nKey: 'col_strategy', formatter: (v) => self._t('strategy_' + v) },
                { key: 'results.production', label: 'Producción', i18nKey: 'col_production', formatter: (v) => v + ' t' },
                { key: 'results.unsold', label: 'No vendido', i18nKey: 'col_unsold', formatter: (v) => v + ' t' },
                { key: 'results.profit', label: 'EBITDA', i18nKey: 'col_profit', formatter: (v) => self._fmtCOP(v) },
                { key: 'results.overallScore', label: 'Nota', i18nKey: 'col_score' }
            ];
        }

        getPresets() { return null; }

        getPerformanceSummary(history) {
            if (!history || !history.length) return {};
            const last = history[history.length - 1];
            const ds = (last && last.domainState) ||
                (window.mySimulation && window.mySimulation.state && window.mySimulation.state.domainState) || {};
            const profits = history.map((r) => (r.results && r.results.profit) || 0);
            const totalProfit = profits.reduce((s, p) => s + p, 0);
            const avgProfit = totalProfit / profits.length;
            const perf = ds.performance || this._score(ds);
            return {
                overallScore: perf.overallScore,
                score: perf.overallScore,
                tier: this._t(perf.tierKey || 'tier_beginner'),
                performance: this._t(perf.tierKey || 'tier_beginner'),
                components: perf.components,
                totalProfit: totalProfit,
                avgProfit: avgProfit,
                cash: ds.cash,
                waterEfficiency: ds.waterEfficiency,
                capexStock: ds.capexStock,
                domainState: ds,
                insights: this._insights(ds)
            };
        }

